/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import * as fs from 'fs'

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

class Scanner {
  constructor(input) {
    this.input = input
    this.pos = 0
    this.line = 1
    this.column = 1
    this.tokens = []
    this.errors = null
  }

  peek(offset = 0) {
    const idx = this.pos + offset
    if (idx >= this.input.length) return null
    return this.input[idx]
  }

  advance() {
    const ch = this.peek()
    if (ch === null) return null

    if (ch === '\n') {
      this.line++
      this.column = 1
    } else if (ch === '\t') {
      // Tab moves to next multiple of 4 plus 1
      this.column = Math.floor((this.column - 1 + 4) / 4) * 4 + 1
    } else {
      this.column++
    }

    this.pos++
    return ch
  }

  skipWhitespace() {
    while (this.peek() !== null) {
      const ch = this.peek()
      if (ch === ' ' || ch === '\t' || ch === '\r' || ch === '\n') {
        this.advance()
      } else {
        break
      }
    }
  }

  skipLineComment() {
    // Already at //, skip both
    this.advance()
    this.advance()

    while (this.peek() !== null && this.peek() !== '\n') {
      this.advance()
    }
  }

  skipBlockComment() {
    // Already at /*, skip both
    const startLine = this.line
    const startColumn = this.column
    this.advance()
    this.advance()

    let depth = 1
    while (depth > 0 && this.peek() !== null) {
      if (this.peek() === '/' && this.peek(1) === '*') {
        this.advance()
        this.advance()
        depth++
      } else if (this.peek() === '*' && this.peek(1) === '/') {
        this.advance()
        this.advance()
        depth--
      } else {
        this.advance()
      }
    }

    if (depth > 0) {
      this.errors = { line: startLine, column: startColumn, msg: 'unterminated block comment' }
    }
  }

  readIdentifier() {
    const startLine = this.line
    const startColumn = this.column
    let value = ''

    while (this.peek() !== null) {
      const ch = this.peek()
      if (/[a-zA-Z0-9_]/.test(ch)) {
        value += ch
        this.advance()
      } else {
        break
      }
    }

    const kind = KEYWORDS.has(value) ? 'keyword' : 'ident'
    return { kind, body: value, line: startLine, column: startColumn }
  }

  readNumber() {
    const startLine = this.line
    const startColumn = this.column
    let value = ''

    // Check for hex, binary, octal
    if (this.peek() === '0' && (this.peek(1) === 'x' || this.peek(1) === 'X')) {
      value += this.advance() // 0
      value += this.advance() // x

      if (!/[0-9a-fA-F]/.test(this.peek())) {
        // No hex digits after 0x
        value += (this.peek() || '')
        if (this.peek() !== null) this.advance()
        this.errors = { line: startLine, column: startColumn, msg: `invalid number ${value}` }
        return null
      }

      while (this.peek() !== null) {
        const ch = this.peek()
        if (/[0-9a-fA-F]/.test(ch)) {
          value += ch
          this.advance()
        } else if (ch === '_') {
          // Check if next is a hex digit
          if (/[0-9a-fA-F]/.test(this.peek(1))) {
            value += ch
            this.advance()
          } else {
            break
          }
        } else {
          break
        }
      }

      // Check for trailing invalid characters
      if (this.peek() !== null) {
        const ch = this.peek()
        if (/[a-zA-Z0-9_]/.test(ch)) {
          value += ch
          this.advance()
          this.errors = { line: startLine, column: startColumn, msg: `invalid number ${value}` }
          return null
        }
      }

      return { kind: 'number', body: value, line: startLine, column: startColumn }
    }

    if (this.peek() === '0' && (this.peek(1) === 'b' || this.peek(1) === 'B')) {
      value += this.advance() // 0
      value += this.advance() // b

      if (!/[01]/.test(this.peek())) {
        value += (this.peek() || '')
        if (this.peek() !== null) this.advance()
        this.errors = { line: startLine, column: startColumn, msg: `invalid number ${value}` }
        return null
      }

