        const ch = this.peek()
        if (/[0-7]/.test(ch)) {
          value += ch
          this.advance()
        } else if (ch === '_') {
          if (/[0-7]/.test(this.peek(1))) {
            value += ch
            this.advance()
          } else {
            break
          }
        } else {
          break
        }
      }

      if (this.peek() !== null) {
        const ch = this.peek()
        if (/[a-zA-Z0-9_]/.test(ch)) {
          value += ch
          this.advance()
          this.errors = { line: startLine, column: startColumn, msg: `invalid number ${value}` }
          return null
        }
      }

      return { kind: 'number', body: value, line: startLine, column: startColumn }
    }

    // Decimal number
    while (this.peek() !== null && /[0-9]/.test(this.peek())) {
      value += this.peek()
      this.advance()
    }

    // Optional underscore between digits
    while (this.peek() === '_' && /[0-9]/.test(this.peek(1))) {
      value += this.peek()
      this.advance()
      while (this.peek() !== null && /[0-9]/.test(this.peek())) {
        value += this.peek()
        this.advance()
      }
    }

    // Optional decimal point
    if (this.peek() === '.' && /[0-9]/.test(this.peek(1))) {
      value += this.peek()
      this.advance()
      while (this.peek() !== null && /[0-9]/.test(this.peek())) {
        value += this.peek()
        this.advance()
      }

      // Optional underscore between digits
      while (this.peek() === '_' && /[0-9]/.test(this.peek(1))) {
        value += this.peek()
        this.advance()
        while (this.peek() !== null && /[0-9]/.test(this.peek())) {
          value += this.peek()
          this.advance()
        }
      }
    }

    // Optional exponent
    if (this.peek() !== null && (this.peek() === 'e' || this.peek() === 'E')) {
      const expStart = this.pos
      value += this.peek()
      this.advance()

      if (this.peek() === '+' || this.peek() === '-') {
        value += this.peek()
        this.advance()
      }

      if (!/[0-9]/.test(this.peek())) {
        // Invalid exponent
        if (this.peek() !== null) {
          value += this.peek()
          this.advance()
        }
        this.errors = { line: startLine, column: startColumn, msg: `invalid number ${value}` }
        return null
      }

      while (this.peek() !== null && /[0-9]/.test(this.peek())) {
        value += this.peek()
        this.advance()
      }

      // Optional underscore between digits
      while (this.peek() === '_' && /[0-9]/.test(this.peek(1))) {
        value += this.peek()
        this.advance()
        while (this.peek() !== null && /[0-9]/.test(this.peek())) {
          value += this.peek()
          this.advance()
        }
      }
    }

    // Check for trailing invalid characters
    if (this.peek() !== null) {
      const ch = this.peek()
      if (/[a-zA-Z_]/.test(ch) || (ch === '.' && /[a-zA-Z0-9_]/.test(this.peek(1)))) {
        value += ch
        this.advance()
        this.errors = { line: startLine, column: startColumn, msg: `invalid number ${value}` }
        return null
      }
    }

    return { kind: 'number', body: value, line: startLine, column: startColumn }
  }

  readString() {
    const startLine = this.line
    const startColumn = this.column

    this.advance() // Skip opening "
    let value = ''

    while (this.peek() !== null) {
      const ch = this.peek()

      if (ch === '\n') {
        this.errors = { line: this.line, column: this.column, msg: 'newline in string' }
        return null
