          value += '\t'
          this.advance()
        } else if (next === 'r') {
          value += '\r'
          this.advance()
        } else if (next === '\\') {
          value += '\\'
          this.advance()
        } else if (next === '"') {
          value += '"'
          this.advance()
        } else if (next === '0') {
