            const backslashColumn = this.column - 2
            this.errors = { line: backslashLine, column: backslashColumn, msg: `invalid escape \\u` }
            return null
          }

          this.advance() // skip {
          let hexDigits = ''

          while (this.peek() !== null && this.peek() !== '}') {
            const ch = this.peek()
            if (!/[0-9a-fA-F]/.test(ch)) {
              const backslashLine = this.line
              const backslashColumn = this.column - hexDigits.length - 3
              this.errors = { line: backslashLine, column: backslashColumn, msg: `invalid escape \\u{...}` }
              return null
