          this.advance() // skip }
        } else {
          const backslashLine = this.line
          const backslashColumn = this.column - 1
          this.errors = { line: backslashLine, column: backslashColumn, msg: `invalid escape \\${next}` }
          return null
        }
      } else {
        value += ch
        this.advance()
      }
    }

    this.errors = { line: startLine, column: startColumn, msg: 'unterminated string' }
    return null
