  readRawString() {
    const startLine = this.line
    const startColumn = this.column

    this.advance() // Skip r
    this.advance() // Skip opening "

    let value = ''

    while (this.peek() !== null) {
      const ch = this.peek()

      if (ch === '"') {
        this.advance()
