          kind: 'rawstring',
          body: JSON.stringify(value),
          line: startLine,
          column: startColumn,
        }
      }

      value += ch
      this.advance()
    }

    this.errors = { line: startLine, column: startColumn, msg: 'unterminated string' }
    return null
  }

  readPunctuation() {
    const startLine = this.line
    const startColumn = this.column
    const twoCharOps = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']

    const ch = this.peek()
    const nextCh = this.peek(1)
    const twoChar = ch + (nextCh || '')

    if (twoCharOps.includes(twoChar)) {
      this.advance()
      this.advance()
      return { kind: 'punct', body: twoChar, line: startLine, column: startColumn }
    }

    const oneCharOps = ['+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.']

    if (oneCharOps.includes(ch)) {
      this.advance()
      return { kind: 'punct', body: ch, line: startLine, column: startColumn }
    }

    return null
  }

  scan() {
    while (this.pos < this.input.length) {
      this.skipWhitespace()

      if (this.pos >= this.input.length) break

      // Check for comments
      if (this.peek() === '/' && this.peek(1) === '/') {
        this.skipLineComment()
        continue
      }

      if (this.peek() === '/' && this.peek(1) === '*') {
        this.skipBlockComment()
        if (this.errors) break
        continue
      }

      const ch = this.peek()

      // Identifier or keyword
      if (/[a-zA-Z_]/.test(ch)) {
        const token = this.readIdentifier()
        this.tokens.push(token)
        continue
      }

      // Number
      if (/[0-9]/.test(ch)) {
        const token = this.readNumber()
        if (this.errors) break
        if (token) this.tokens.push(token)
        continue
      }

      // String
      if (ch === '"') {
        const token = this.readString()
        if (this.errors) break
        if (token) this.tokens.push(token)
        continue
      }

      // Raw string
      if (ch === 'r' && this.peek(1) === '"') {
        const token = this.readRawString()
        if (this.errors) break
        if (token) this.tokens.push(token)
        continue
      }

      // Punctuation
      const token = this.readPunctuation()
      if (token) {
        this.tokens.push(token)
        continue
      }

      // Unexpected character
      this.errors = { line: this.line, column: this.column, msg: `unexpected character ${ch}` }
      break
    }
  }
}

async function main() {
  const args = process.argv.slice(2)

  if (args.length !== 1 || !['tokens', 'stats'].includes(args[0])) {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
  }

  const mode = args[0]

  // Read from stdin
  const input = await new Promise((resolve, reject) => {
    let data = ''
    process.stdin.setEncoding('utf8')
    process.stdin.on('data', chunk => { data += chunk })
    process.stdin.on('end', () => { resolve(data) })
    process.stdin.on('error', reject)
  })

  const scanner = new Scanner(input)
  scanner.scan()

  if (scanner.errors) {
    const { line, column, msg } = scanner.errors
    process.stderr.write(`error: ${line}:${column}: ${msg}\n`)
    process.exit(2)
  }

  if (mode === 'tokens') {
    for (const token of scanner.tokens) {
      process.stdout.write(`${token.line}:${token.column} ${token.kind} ${token.body}\n`)
    }
  } else {
    const counts = {
      ident: 0,
      keyword: 0,
      number: 0,
      punct: 0,
      rawstring: 0,
      string: 0,
    }

    for (const token of scanner.tokens) {
      counts[token.kind]++
    }

    let total = 0
    for (const kind of ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']) {
      process.stdout.write(`${kind} ${counts[kind]}\n`)
      total += counts[kind]
    }
    process.stdout.write(`total ${total}\n`)
  }

  process.exit(0)
}

main().catch(err => {
  process.stderr.write(`error: ${err.message}\n`)
  process.exit(2)
})
"}

