    const prefix = this.peek() === '0' ? this.peek(1) : null
    let isDigit = null
    if (prefix === 'x' || prefix === 'X') isDigit = isHex
    else if (prefix === 'b' || prefix === 'B') isDigit = isBin
    else if (prefix === 'o' || prefix === 'O') isDigit = isOct

    if (isDigit !== null) {
      sink.text += this.take()
      sink.text += this.take()
      if (this.readDigits(isDigit, sink) === 0) {
        sink.text += this.takeWordRun()
        throw new ScanError(line, column, `invalid number ${sink.text}`)
