    } else {
      this.readDigits(isDec, sink)
      // A `.` only continues the number when a digit follows it.
      if (this.peek() === '.' && isDec(this.peek(1))) {
        sink.text += this.take()
        this.readDigits(isDec, sink)
      }
      // An exponent marker only continues it when a digit, or a sign and then
      // a digit, follows.
      const marker = this.peek()
      if (marker === 'e' || marker === 'E') {
        const next = this.peek(1)
        const signed = (next === '+' || next === '-') && isDec(this.peek(2))
        if (isDec(next) || signed) {
          sink.text += this.take()
          if (signed) sink.text += this.take()
          this.readDigits(isDec, sink)
        }
      }
    }

    if (isWord(this.peek())) {
      sink.text += this.takeWordRun()
      throw new ScanError(line, column, `invalid number ${sink.text}`)
    }
    return { kind: 'number', line, column, body: sink.text }
  }

  readString() {
    const line = this.line
    const column = this.column
    this.take()
    let value = ''
    for (;;) {
      if (this.atEnd()) throw new ScanError(line, column, 'unterminated string')
      const ch = this.peek()
      if (ch === '"') {
