      if (ch === '\n') throw new ScanError(this.line, this.column, 'newline in string')
      if (ch === '\\') {
        value += this.readEscape(line, column)
      } else {
        value += this.take()
      }
    }
  }

  readEscape(stringLine, stringColumn) {
    const line = this.line
    const column = this.column
    this.take()
    if (this.atEnd()) throw new ScanError(stringLine, stringColumn, 'unterminated string')
    const marker = this.take()
    const bad = () => new ScanError(line, column, `invalid escape \\${marker}`)
    switch (marker) {
      case 'n':
        return '\n'
      case 't':
        return '\t'
      case 'r':
        return '\r'
      case '\\':
        return '\\'
      case '"':
        return '"'
      case '0':
        return '\0'
      case 'x': {
        if (!isHex(this.peek()) || !isHex(this.peek(1))) throw bad()
        const digits = this.take() + this.take()
        return String.fromCharCode(parseInt(digits, 16))
      }
      case 'u': {
        if (this.peek() !== '{') throw bad()
        this.take()
        let digits = ''
        while (isHex(this.peek())) digits += this.take()
        if (digits.length === 0 || this.peek() !== '}') throw bad()
        const code = parseInt(digits, 16)
        if (!(code <= 0x10ffff)) throw bad()
        this.take()
        return String.fromCodePoint(code)
      }
      default:
        throw bad()
    }
  }

  readRawString() {
    const line = this.line
    const column = this.column
    this.take()
    this.take()
    let value = ''
    for (;;) {
      if (this.atEnd()) throw new ScanError(line, column, 'unterminated string')
      const ch = this.take()
      if (ch === '"') return { kind: 'rawstring', line, column, body: JSON.stringify(value) }
      value += ch
    }
  }

  readPunct() {
    const line = this.line
    const column = this.column
    const pair = this.peek() + (this.peek(1) ?? '')
    if (PUNCT2.includes(pair)) {
      this.take()
      this.take()
      return { kind: 'punct', line, column, body: pair }
    }
    const ch = this.peek()
    if (PUNCT1.includes(ch)) {
      this.take()
      return { kind: 'punct', line, column, body: ch }
    }
    throw new ScanError(line, column, `unexpected character ${ch}`)
  }
}

export const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

export function scan(source) {
  return new Scanner(source).scan()
}
