export class ScanError extends Error {
  constructor(line, column, reason) {
    super(`${line}:${column}: ${reason}`)
    this.line = line
    this.column = column
    this.reason = reason
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const PUNCT2 = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT1 = ['+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.']

const isDec = (c) => c !== null && c >= '0' && c <= '9'
const isHex = (c) => c !== null && /^[0-9a-fA-F]$/.test(c)
const isBin = (c) => c === '0' || c === '1'
const isOct = (c) => c !== null && c >= '0' && c <= '7'
const isAlpha = (c) => c !== null && /^[A-Za-z_]$/.test(c)
const isWord = (c) => c !== null && /^[0-9A-Za-z_]$/.test(c)

class Scanner {
  constructor(source) {
    // Positions count code points, so the input is walked code point by code
    // point rather than by UTF-16 unit.
    this.chars = Array.from(source)
    this.pos = 0
    this.line = 1
    this.column = 1
  }

  peek(offset = 0) {
    const index = this.pos + offset
    return index < this.chars.length ? this.chars[index] : null
  }

  atEnd() {
    return this.pos >= this.chars.length
  }

  take() {
    const ch = this.chars[this.pos]
    this.pos += 1
    if (ch === '\n') {
      this.line += 1
      this.column = 1
    } else if (ch === '\t') {
      this.column = Math.floor((this.column - 1) / 4) * 4 + 5
    } else {
      this.column += 1
    }
    return ch
  }

