  takeWordRun() {
    let text = ''
    while (isWord(this.peek())) text += this.take()
    return text
  }

  scan() {
    const tokens = []
    for (;;) {
      this.skipTrivia()
      if (this.atEnd()) return tokens
      tokens.push(this.readToken())
    }
  }

  skipTrivia() {
    for (;;) {
      const ch = this.peek()
      if (ch === ' ' || ch === '\t' || ch === '\r' || ch === '\n') {
        this.take()
      } else if (ch === '/' && this.peek(1) === '/') {
        while (!this.atEnd() && this.peek() !== '\n') this.take()
      } else if (ch === '/' && this.peek(1) === '*') {
        this.skipBlockComment()
      } else {
        return
      }
    }
  }

  skipBlockComment() {
    const line = this.line
    const column = this.column
    this.take()
    this.take()
    let depth = 1
    while (depth > 0) {
      if (this.atEnd()) throw new ScanError(line, column, 'unterminated block comment')
      if (this.peek() === '/' && this.peek(1) === '*') {
        this.take()
        this.take()
        depth += 1
      } else if (this.peek() === '*' && this.peek(1) === '/') {
        this.take()
        this.take()
        depth -= 1
      } else {
        this.take()
      }
    }
  }

  readToken() {
    const ch = this.peek()
    if (ch === 'r' && this.peek(1) === '"') return this.readRawString()
    if (isAlpha(ch)) return this.readWord()
    if (isDec(ch)) return this.readNumber()
    if (ch === '"') return this.readString()
    return this.readPunct()
  }

  readWord() {
    const line = this.line
    const column = this.column
    let text = ''
    while (isWord(this.peek())) text += this.take()
