  readString() {
    const startLine = this.line
    const startColumn = this.column

    this.advance() // Skip opening "
    let value = ''

    while (this.peek() !== null) {
      const ch = this.peek()

      if (ch === '\n') {
        this.errors = { line: this.line, column: this.column, msg: 'newline in string' }
        return null
      }

      if (ch === '"') {
        this.advance()
        // Convert to JSON representation
        return {
          kind: 'string',
          body: JSON.stringify(value),
          line: startLine,
          column: startColumn,
        }
      }

      if (ch === '\\') {
        this.advance()
        const next = this.peek()

        if (next === null) {
          this.errors = { line: startLine, column: startColumn, msg: 'unterminated string' }
          return null
        }

        if (next === 'n') {
          value += '\n'
          this.advance()
        } else if (next === 't') {
          value += '\t'
          this.advance()
        } else if (next === 'r') {
          value += '\r'
          this.advance()
        } else if (next === '\\') {
          value += '\\'
          this.advance()
        } else if (next === '"') {
          value += '"'
          this.advance()
        } else if (next === '0') {
          value += '\0'
          this.advance()
        } else if (next === 'x') {
          this.advance()
          const hex1 = this.peek()
          const hex2 = this.peek(1)

          if (!/[0-9a-fA-F]/.test(hex1) || !/[0-9a-fA-F]/.test(hex2)) {
            const backslashLine = this.line
            const backslashColumn = this.column - 1
            this.errors = { line: backslashLine, column: backslashColumn, msg: `invalid escape \\${next}` }
            return null
          }

          const hex = this.peek() + this.peek(1)
          value += String.fromCharCode(parseInt(hex, 16))
          this.advance()
          this.advance()
        } else if (next === 'u') {
          this.advance()

          if (this.peek() !== '{') {
            const backslashLine = this.line
            const backslashColumn = this.column - 2
            this.errors = { line: backslashLine, column: backslashColumn, msg: `invalid escape \\u` }
            return null
          }

          this.advance() // skip {
          let hexDigits = ''

          while (this.peek() !== null && this.peek() !== '}') {
            const ch = this.peek()
            if (!/[0-9a-fA-F]/.test(ch)) {
              const backslashLine = this.line
              const backslashColumn = this.column - hexDigits.length - 3
              this.errors = { line: backslashLine, column: backslashColumn, msg: `invalid escape \\u{...}` }
              return null
            }
            hexDigits += ch
            this.advance()
          }

          if (this.peek() !== '}') {
            const backslashLine = this.line
            const backslashColumn = this.column - hexDigits.length - 3
            this.errors = { line: backslashLine, column: backslashColumn, msg: 'unterminated string' }
            return null
          }

          if (hexDigits.length === 0) {
            const backslashLine = this.line
            const backslashColumn = this.column - 2
            this.errors = { line: backslashLine, column: backslashColumn, msg: `invalid escape \\u` }
            return null
          }

          const codePoint = parseInt(hexDigits, 16)
          if (codePoint > 0x10FFFF) {
            const backslashLine = this.line
            const backslashColumn = this.column - hexDigits.length - 3
            this.errors = { line: backslashLine, column: backslashColumn, msg: `invalid escape \\u{...}` }
            return null
          }

          value += String.fromCodePoint(codePoint)
          this.advance() // skip }
        } else {
          const backslashLine = this.line
          const backslashColumn = this.column - 1
          this.errors = { line: backslashLine, column: backslashColumn, msg: `invalid escape \\${next}` }
          return null
        }
      } else {
        value += ch
        this.advance()
      }
    }

    this.errors = { line: startLine, column: startColumn, msg: 'unterminated string' }
    return null
  }

  readRawString() {
    const startLine = this.line
    const startColumn = this.column

    this.advance() // Skip r
    this.advance() // Skip opening "

    let value = ''

    while (this.peek() !== null) {
      const ch = this.peek()

      if (ch === '"') {
        this.advance()
        return {
          kind: 'rawstring',
          body: JSON.stringify(value),
          line: startLine,
          column: startColumn,
        }
      }

      value += ch
      this.advance()
    }

    this.errors = { line: startLine, column: startColumn, msg: 'unterminated string' }
    return null
  }

  readPunctuation() {
    const startLine = this.line
    const startColumn = this.column
    const twoCharOps = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']

    const ch = this.peek()
    const nextCh = this.peek(1)
    const twoChar = ch + (nextCh || '')

    if (twoCharOps.includes(twoChar)) {
      this.advance()
      this.advance()
      return { kind: 'punct', body: twoChar, line: startLine, column: startColumn }
    }

    const oneCharOps = ['+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.']

    if (oneCharOps.includes(ch)) {
      this.advance()
      return { kind: 'punct', body: ch, line: startLine, column: startColumn }
    }

    return null
  }

  scan() {
    while (this.pos < this.input.length) {
      this.skipWhitespace()

      if (this.pos >= this.input.length) break

      // Check for comments
      if (this.peek() === '/' && this.peek(1) === '/') {
        this.skipLineComment()
        continue
      }

      if (this.peek() === '/' && this.peek(1) === '*') {
        this.skipBlockComment()
        if (this.errors) break
        continue
      }

      const ch = this.peek()

      // Raw string (must be before identifier check)
      if (ch === 'r' && this.peek(1) === '"') {
        const token = this.readRawString()
        if (this.errors) break
        if (token) this.tokens.push(token)
        continue
      }

      // Identifier or keyword
      if (/[a-zA-Z_]/.test(ch)) {
        const token = this.readIdentifier()
        this.tokens.push(token)
        continue
      }

      // Number
      if (/[0-9]/.test(ch)) {
        const token = this.readNumber()
        if (this.errors) break
        if (token) this.tokens.push(token)
        continue
      }

      // String
      if (ch === '"') {
        const token = this.readString()
        if (this.errors) break
        if (token) this.tokens.push(token)
        continue
      }

      // Punctuation
      const token = this.readPunctuation()
      if (token) {
        this.tokens.push(token)
        continue
      }

      // Unexpected character
      this.errors = { line: this.line, column: this.column, msg: `unexpected character ${ch}` }
      break
    }
  }
}

async function main() {
  const args = process.argv.slice(2)

  if (args.length !== 1 || !['tokens', 'stats'].includes(args[0])) {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
  }

  const mode = args[0]

  // Read from stdin
  const input = await new Promise((resolve, reject) => {
    let data = ''
    process.stdin.setEncoding('utf8')
    process.stdin.on('data', chunk => { data += chunk })
    process.stdin.on('end', () => { resolve(data) })
    process.stdin.on('error', reject)
  })

  const scanner = new Scanner(input)
  scanner.scan()

  if (scanner.errors) {
    const { line, column, msg } = scanner.errors
    process.stderr.write(`error: ${line}:${column}: ${msg}\n`)
    process.exit(2)
  }

  if (mode === 'tokens') {
    for (const token of scanner.tokens) {
      process.stdout.write(`${token.line}:${token.column} ${token.kind} ${token.body}\n`)
    }
  } else {
    const counts = {
      ident: 0,
      keyword: 0,
      number: 0,
      punct: 0,
      rawstring: 0,
      string: 0,
    }

    for (const token of scanner.tokens) {
      counts[token.kind]++
    }

    let total = 0
    for (const kind of ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']) {
      process.stdout.write(`${kind} ${counts[kind]}\n`)
      total += counts[kind]
    }
    process.stdout.write(`total ${total}\n`)
  }

  process.exit(0)
}

main().catch(err => {
  process.stderr.write(`error: ${err.message}\n`)
  process.exit(2)
})

