import { scan, ScanError, KINDS } from './scanner.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exitCode = 2
}

function readStdin() {
  return new Promise((resolve, reject) => {
    const chunks = []
    process.stdin.on('data', (chunk) => chunks.push(chunk))
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

function render(mode, tokens) {
  if (mode === 'tokens') {
    return tokens.map((token) => `${token.line}:${token.column} ${token.kind} ${token.body}\n`).join('')
  }
  const counts = new Map(KINDS.map((kind) => [kind, 0]))
  for (const token of tokens) counts.set(token.kind, counts.get(token.kind) + 1)
  const lines = KINDS.map((kind) => `${kind} ${counts.get(kind)}\n`)
  lines.push(`total ${tokens.length}\n`)
  return lines.join('')
}

async function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
    fail('usage: cli.js tokens|stats')
    return
  }
  const source = await readStdin()
  let output
  try {
    output = render(args[0], scan(source))
  } catch (error) {
    if (error instanceof ScanError) {
      fail(`${error.line}:${error.column}: ${error.reason}`)
      return
    }
    throw error
  }
  if (output !== '') process.stdout.write(output)
}

main().catch((error) => {
  fail(String(error && error.message ? error.message : error))
})
